package it.servizidigitali.gestionebandi.operatore.frontend.portlet.action;

import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.portlet.bridges.mvc.BaseMVCActionCommand;
import com.liferay.portal.kernel.portlet.bridges.mvc.MVCActionCommand;
import com.liferay.portal.kernel.service.ServiceContext;
import com.liferay.portal.kernel.service.ServiceContextFactory;
import com.liferay.portal.kernel.servlet.SessionErrors;
import com.liferay.portal.kernel.util.ParamUtil;
import com.liferay.portal.kernel.util.Validator;

import java.util.Arrays;
import java.util.stream.Collectors;

import javax.portlet.ActionRequest;
import javax.portlet.ActionResponse;
import javax.portlet.MutableRenderParameters;

import it.servizidigitali.audit.common.service.AuditService;
import it.servizidigitali.common.utility.exception.FirmaDigitaleRemotaException;
import it.servizidigitali.common.utility.exception.DataAccessException;
import it.servizidigitali.common.utility.exception.KosmosException;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.communication.exception.CommunicationException;
import it.servizidigitali.gestionebandi.operatore.frontend.constants.ScrivaniaOperatoreBandiPortletKeys;
import it.servizidigitali.gestionebandi.operatore.frontend.enums.DomandaBandoTabEnum;
import it.servizidigitali.gestionebandi.operatore.frontend.service.ScrivaniaOperatoreBandiFrontendService;

@Component(immediate = true, service = MVCActionCommand.class, property = {
        "javax.portlet.name=" + ScrivaniaOperatoreBandiPortletKeys.SCRIVANIA_OPERATORE_BANDI,
        "mvc.command.name=/action/richiediIntegrazione"
})
public class RichiediIntegrazioneActionCommand extends BaseMVCActionCommand {

    public static final Log log = LogFactoryUtil.getLog(RichiediIntegrazioneActionCommand.class);

    @Reference
    private ScrivaniaOperatoreBandiFrontendService scrivaniaOperatoreBandiFrontendService;

    @Reference
    private AuditService auditService;

    @Override
    protected void doProcessAction(ActionRequest actionRequest, ActionResponse actionResponse) throws Exception {
        long domandaBandoId = ParamUtil.getLong(actionRequest, "domandaBandoId");
        String queryTab = ParamUtil.getString(actionRequest, "queryTab");
        String oggetto = ParamUtil.getString(actionRequest, "oggettoIntegrazione");
        String note = ParamUtil.getString(actionRequest, "noteIntegrazione");
        String tipoIntegrazione = ParamUtil.getString(actionRequest, "tipoIntegrazione");
        long[] integrazioni = ParamUtil.getLongValues(actionRequest, "integrazioni");
        String[] allegati = ParamUtil.getStringValues(actionRequest, "allegati");
        String codiceAzioneUtente=ParamUtil.getString(actionRequest, "codiceAzioneUtente");
        String codiceOtpFirma = ParamUtil.getString(actionRequest, "codiceOtpFirma");
        String password = ParamUtil.getString(actionRequest, "passwordFdr");
        boolean checkFirmaRichiestaIntegrazione = ParamUtil.getBoolean(actionRequest, "checkRichiestaIntegrazione");

        boolean campoOggettoAttivo = scrivaniaOperatoreBandiFrontendService.isCampoOggettoAttivo(domandaBandoId);
        validateInput(oggetto, note, campoOggettoAttivo);

        ServiceContext serviceContext = ServiceContextFactory.getInstance(actionRequest);
        MutableRenderParameters renderParameters = actionResponse.getRenderParameters();
        boolean erroreRichiestaIntegrazione = false;

        try {
            scrivaniaOperatoreBandiFrontendService.sendNotificaRichiestaintegrazione(domandaBandoId);


        }catch(CommunicationException e) {
            log.error("Errore durante l'invio della comunicazione di richiesta integrazione all'operatore per la domanda bando con ID: " + domandaBandoId);
            auditService.saveErrorLog(actionRequest, e.getMessage());
        }

        try {
            scrivaniaOperatoreBandiFrontendService.richiediIntegrazioni(
                    serviceContext,
                    domandaBandoId,
                    tipoIntegrazione,
                    oggetto,
                    note,
                    Arrays.stream(integrazioni).boxed().collect(Collectors.toList()),
                    Arrays.stream(allegati).collect(Collectors.toList()), codiceAzioneUtente, codiceOtpFirma, password, checkFirmaRichiestaIntegrazione
            );
        } catch (FirmaDigitaleRemotaException e) {
            log.error("Errore firma digitale durante richiesta integrazione per domanda bando con ID: " + domandaBandoId, e);
            auditService.saveErrorLog(actionRequest, e.getMessage());
            SessionErrors.add(actionRequest, e.getClass().getName(), e.getMessage());
            renderParameters.setValue("mvcRenderCommandName", "/dettaglio_domanda_bando");
            renderParameters.setValue("domandaBandoId", String.valueOf(domandaBandoId));
            renderParameters.setValue("queryTab", queryTab);
            renderParameters.setValue("queryTabParent", DomandaBandoTabEnum.IN_LAVORAZIONE.getKey());
            return;
        } catch (KosmosException e) {
            log.error("Errore protocollazione durante richiesta integrazione per domanda bando con ID: " + domandaBandoId, e);
            auditService.saveErrorLog(actionRequest, e.getMessage());
            SessionErrors.add(actionRequest, e.getClass().getName(), e.getMessage());
            renderParameters.setValue("mvcRenderCommandName", "/dettaglio_domanda_bando");
            renderParameters.setValue("domandaBandoId", String.valueOf(domandaBandoId));
            renderParameters.setValue("queryTab", queryTab);
            renderParameters.setValue("queryTabParent", DomandaBandoTabEnum.IN_LAVORAZIONE.getKey());
            return;
        } catch (DataAccessException e) {
            log.error("Errore salvataggio durante richiesta integrazione per domanda bando con ID: " + domandaBandoId, e);
            auditService.saveErrorLog(actionRequest, e.getMessage());
            SessionErrors.add(actionRequest, e.getClass().getName(), e.getMessage());
            renderParameters.setValue("mvcRenderCommandName", "/dettaglio_domanda_bando");
            renderParameters.setValue("domandaBandoId", String.valueOf(domandaBandoId));
            renderParameters.setValue("queryTab", queryTab);
            renderParameters.setValue("queryTabParent", DomandaBandoTabEnum.IN_LAVORAZIONE.getKey());
            return;
        } catch(Exception e) {
            log.error("Errore durante richiesta integrazione per domanda bando con ID: " + domandaBandoId, e);
            auditService.saveErrorLog(actionRequest, e.getMessage());

            // Cerca ricorsivamente nella catena delle cause per trovare le nostre eccezioni custom
            Throwable cause = e;
            boolean foundCustomException = false;
            while (cause != null && !foundCustomException) {
                if (cause instanceof FirmaDigitaleRemotaException) {
                    SessionErrors.add(actionRequest, FirmaDigitaleRemotaException.class.getName(), cause.getMessage());
                    foundCustomException = true;
                } else if (cause instanceof KosmosException) {
                    SessionErrors.add(actionRequest, KosmosException.class.getName(), cause.getMessage());
                    foundCustomException = true;
                } else if (cause instanceof DataAccessException) {
                    SessionErrors.add(actionRequest, DataAccessException.class.getName(), cause.getMessage());
                    foundCustomException = true;
                }
                cause = cause.getCause();
            }

            if (!foundCustomException) {
                erroreRichiestaIntegrazione = true;
            }

            renderParameters.setValue("mvcRenderCommandName", "/dettaglio_domanda_bando");
            renderParameters.setValue("domandaBandoId", String.valueOf(domandaBandoId));
            renderParameters.setValue("queryTab", queryTab);
            renderParameters.setValue("queryTabParent", DomandaBandoTabEnum.IN_LAVORAZIONE.getKey());
            renderParameters.setValue("erroreRichiestaIntegrazione", String.valueOf(erroreRichiestaIntegrazione));
            return;
        }

        renderParameters.setValue("mvcRenderCommandName", "/dettaglio_domanda_bando");
        renderParameters.setValue("domandaBandoId", String.valueOf(domandaBandoId));
        renderParameters.setValue("queryTab", queryTab);
        renderParameters.setValue("queryTabParent", DomandaBandoTabEnum.IN_LAVORAZIONE.getKey());
        renderParameters.setValue("erroreRichiestaIntegrazione", String.valueOf(erroreRichiestaIntegrazione));
    }

    private void validateInput(String oggetto, String note, boolean campoOggettoAttivo) {
        if (campoOggettoAttivo && Validator.isBlank(oggetto)) {
            throw new IllegalArgumentException("Oggetto è obbligatorio");
        }

        if (oggetto != null && oggetto.length() > 100) {
            throw new IllegalArgumentException("Oggetto deve essere al max di 100 caratteri");
        }

        if (Validator.isBlank(note)) {
            throw new IllegalArgumentException("Note è obbligatorio");
        }

        if (note.length() > 1000) {
            throw new IllegalArgumentException("Note deve essere al max di 1000 caratteri");
        }
    }
}

