Documento documento = new Documento();
try {
    documento.setContenuto(file.getInputStream().readAllBytes());
} catch (Exception e) {
    throw new DataAccessException("Errore durante la lettura del file", e);
}
documento.setNome("Richiesta integrazione ID " + domandaBando.getDomandaBandoId() + ".pdf" );
documento.setOggetto("Richiesta integrazione ID " + domandaBando.getDomandaBandoId());
documento.setTipo(null);
documento.setTipoMIME(null);
documento.setTitolo("Richiesta integrazione ID " + domandaBando.getDomandaBandoId());

request.setDocumento(documento);

if (isProtocollazioneAllegatiIntegrazioneAttiva(bando)) {
    List<Documento> allegatiSecondariProtocollo = costruisciAllegatiSecondariProtocollo(allegatiEsterni);
    request.setAllegati(allegatiSecondariProtocollo);
} else {
    request.setAllegati(new ArrayList<>());
}

request.setOggetto("Richiesta integrazione " + bando.getNome());
request.setOrigine(origine);

if (Validator.isNotNull(bando.getCodiceAOO())) {
    request.setCodiceAOO(bando.getCodiceAOO());
}

if (Validator.isNotNull(bando.getCodiceUO())) {
    request.setCodiceUO(bando.getCodiceUO());
}

// Creazione gerarchia sottofascicoli Kosmos PRIMA della protocollazione del documento.
// Errori nella creazione di un livello (L1/L2/L3) NON bloccano la protocollazione:
// si effettua fallback al livello superiore (L3 -> L2 -> L1 -> L0 = bando.idPratica).
if (bando.isAbilitaSottoFascicolazione()) {
    String idFascicoloPadre = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
            List.of(domandaBando.getDomandaBandoId()),
            List.of(IdentificativoFascicoloEnum.ID_FASCICOLO_ISTANZA.name())
    ).stream().findFirst().map(DomandaBandoDatoAggiuntivo::getValore).orElse(null);
    if (Validator.isNull(idFascicoloPadre)) {
        try {
            SottoFascicoloRequest sottoFascicoloRequest = new SottoFascicoloRequest();
            sottoFascicoloRequest.setContesto(Contesto.valueOf(bando.getContesto()));
            sottoFascicoloRequest.setGroupId(domandaBando.getGroupId());
            sottoFascicoloRequest.setCodiceAoo(bando.getCodiceAOO());
            sottoFascicoloRequest.setFascicoloId(bando.getIdPratica());
            sottoFascicoloRequest.setClassifica(bando.getClassifica());
            sottoFascicoloRequest.setUfficioResp(bando.getMittenteInterno());
            sottoFascicoloRequest.setiFA(bando.isIFA());
            sottoFascicoloRequest.setTipoProtocolloClient(bando.getTipoProtocolloClient());
            sottoFascicoloRequest.setOggetto(FASCICOLO_ISTANZA_ID + domandaBando.getDomandaBandoId());
            idFascicoloPadre = protocolloService.creaSottoFascicolo(sottoFascicoloRequest);
            if (Validator.isNotNull(idFascicoloPadre)) {
                salvaDatoAggiuntivoSafe(domandaBando, IdentificativoFascicoloEnum.ID_FASCICOLO_ISTANZA.name(), idFascicoloPadre);
            }
        } catch (Exception e) {
            log.error("protocollaRichiestaIntegrazione :: creazione L1 fallita per domandaBandoId="
                    + domandaBando.getDomandaBandoId() + ": " + e.getMessage(), e);
            idFascicoloPadre = null;
        }
    }

    String faseWorkflowBando = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
            List.of(domandaBando.getDomandaBandoId()),
            List.of("FASE_WORKFLOW_BANDO")
    ).stream().findFirst().map(DomandaBandoDatoAggiuntivo::getValore).orElse(null);
    String identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_ACQUISIZIONE_ISTANZA.name();
    if (Validator.isNotNull(faseWorkflowBando)) {
        try {
            FaseWorkflowBandoEnum faseWorkflowBandoEnum = FaseWorkflowBandoEnum.valueOf(faseWorkflowBando);
            switch (faseWorkflowBandoEnum) {
                case ISTRUTTORIA:
                    identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_ISTRUTTORIA.name();
                    break;
                case VERIFICA_RESPONSABILE:
                    identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_VERIFICA_RESPONSABILE.name();
                    break;
                case VALUTAZIONE:
                    identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_VALUTAZIONE.name();
                    break;
                case CONCESSIONE:
                    identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_CONCESSIONE.name();
                    break;
                case ESECUZIONE:
                    identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_ESECUZIONE.name();
                    break;
                case PARTECIPAZIONE:
                    identificativoFascicolo = IdentificativoFascicoloEnum.ID_FASCICOLO_PARTECIPAZIONE.name();
                    break;
            }
        } catch (IllegalArgumentException e) {
            log.warn("protocollaRichiestaIntegrazione :: fase workflow non riconosciuta '" + faseWorkflowBando + "'");
        }
    }
    String idFascicoloFase = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(
            List.of(domandaBando.getDomandaBandoId()),
            List.of(identificativoFascicolo)
    ).stream().findFirst().map(DomandaBandoDatoAggiuntivo::getValore).orElse(null);
    if (Validator.isNotNull(faseWorkflowBando) && Validator.isNull(idFascicoloFase) && Validator.isNotNull(idFascicoloPadre)) {
        try {
            SottoFascicoloRequest sottoFascicoloRequest = new SottoFascicoloRequest();
            sottoFascicoloRequest.setContesto(Contesto.valueOf(bando.getContesto()));
            sottoFascicoloRequest.setGroupId(domandaBando.getGroupId());
            sottoFascicoloRequest.setCodiceAoo(bando.getCodiceAOO());
            sottoFascicoloRequest.setFascicoloId(idFascicoloPadre);
            sottoFascicoloRequest.setClassifica(bando.getClassifica());
            sottoFascicoloRequest.setUfficioResp(bando.getMittenteInterno());
            sottoFascicoloRequest.setiFA(bando.isIFA());
            sottoFascicoloRequest.setTipoProtocolloClient(bando.getTipoProtocolloClient());
            sottoFascicoloRequest.setOggetto(ISTANZA + domandaBando.getDomandaBandoId() + " - " + getFaseLabel(faseWorkflowBando));
            idFascicoloFase = protocolloService.creaSottoFascicolo(sottoFascicoloRequest);
            if (Validator.isNotNull(idFascicoloFase)) {
                salvaDatoAggiuntivoSafe(domandaBando, identificativoFascicolo, idFascicoloFase);
            }
        } catch (Exception e) {
            log.error("protocollaRichiestaIntegrazione :: creazione L2 fallita per domandaBandoId="
                    + domandaBando.getDomandaBandoId() + ": " + e.getMessage(), e);
            idFascicoloFase = null;
        }
    }

    List<BandoForm> bandoForms = bandoFormLocalService.getBandoFormBandoAndForm(bando.getBandoId(), istanzaDomandaBando.getFormId());
    String idSottoFascicoloDomandaAggiuntiva = null;
    Form formRichiesta = null;
    if (ListUtil.isNotEmpty(bandoForms) && bandoForms.size() == 1) {
        idSottoFascicoloDomandaAggiuntiva = getIdSottoFascicoloDomandaAggiuntiva(true, bando, bandoForms, domandaBando);
        formRichiesta = formLocalService.fetchForm(bandoForms.get(0).getFormId());
    }
    String idFascicoloPadreL3 = Validator.isNotNull(idSottoFascicoloDomandaAggiuntiva) ? idSottoFascicoloDomandaAggiuntiva : idFascicoloFase;
    String idSottoFascicoloIntegrazione = istanzaDomandaBando.getIdSottoFascicolo();
    if (Validator.isNull(idSottoFascicoloIntegrazione) && Validator.isNotNull(idFascicoloPadreL3)) {
        try {
            SottoFascicoloRequest sottoFascicoloRequest = new SottoFascicoloRequest();
            sottoFascicoloRequest.setContesto(Contesto.valueOf(bando.getContesto()));
            sottoFascicoloRequest.setGroupId(domandaBando.getGroupId());
            sottoFascicoloRequest.setCodiceAoo(bando.getCodiceAOO());
            sottoFascicoloRequest.setFascicoloId(idFascicoloPadreL3);
            sottoFascicoloRequest.setClassifica(bando.getClassifica());
            sottoFascicoloRequest.setUfficioResp(bando.getMittenteInterno());
            sottoFascicoloRequest.setiFA(bando.isIFA());
            sottoFascicoloRequest.setTipoProtocolloClient(bando.getTipoProtocolloClient());
            String oggettoL3Op = Validator.isNotNull(formRichiesta)
                    ? FASCICOLO_INTEGRAZIONE + formRichiesta.getNome() + " " + istanzaDomandaBando.getIstanzaDomandaBandoId()
                    : FASCICOLO_INTEGRAZIONE + istanzaDomandaBando.getIstanzaDomandaBandoId();
            sottoFascicoloRequest.setOggetto(oggettoL3Op);
            idSottoFascicoloIntegrazione = protocolloService.creaSottoFascicolo(sottoFascicoloRequest);
            if (Validator.isNotNull(idSottoFascicoloIntegrazione)) {
                istanzaDomandaBando.setIdSottoFascicolo(idSottoFascicoloIntegrazione);
                try {
                    istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanzaDomandaBando);
                } catch (Exception e) {
                    log.error("protocollaRichiestaIntegrazione :: update istanzaDomandaBando.idSottoFascicolo fallito: " + e.getMessage(), e);
                }
            }
        } catch (Exception e) {
            log.error("protocollaRichiestaIntegrazione :: creazione L3 fallita per domandaBandoId="
                    + domandaBando.getDomandaBandoId() + ": " + e.getMessage(), e);
            idSottoFascicoloIntegrazione = null;
        }
    }

    // Override request.setIdPratica con priorità: L3 > L2 > L1 > L0 (L0 = setIdPratica iniziale a riga 657).
    if (Validator.isNotNull(idSottoFascicoloIntegrazione)) {
        request.setIdPratica(idSottoFascicoloIntegrazione);
    } else if (Validator.isNotNull(idFascicoloFase)) {
        request.setIdPratica(idFascicoloFase);
    } else if (Validator.isNotNull(idFascicoloPadre)) {
        request.setIdPratica(idFascicoloPadre);
    }
}

