    if(Validator.isNotNull(bando.getClassifica())){
        request.setClassifica(bando.getClassifica());
    }

    if(Validator.isNotNull(bando.getTipoProtocolloClient())){
        request.setTipoProtocolloClient(bando.getTipoProtocolloClient());
    }

